Action: run_sql({'query': 'WITH matched AS (\n  SELECT\n    e.gmap_id,\n    e.avg_rating,\n    COUNT(v.violation_id) AS total_violation_rows,\n    COUNT(v.violation_id) FILTER (WHERE vc.critical) AS critical_violation_rows\n  FROM establishments e\n  JOIN inspections i ON i.slchd_establishment_key = e.slchd_establishment_key\n  LEFT JOIN violations v ON v.inspection_id = i.inspection_id\n  LEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id\n  WHERE e.avg_rating IS NOT NULL\n  GROUP BY e.gmap_id, e.avg_rating\n), stats AS (\n  SELECT\n    COUNT(*) AS matched_restaurants,\n    corr(avg_rating, total_violation_rows) AS rating_total_violation_correlation,\n    corr(avg_rating, critical_violation_rows) AS rating_critical_violation_correlation,\n    avg(avg_rating) AS mean_rating,\n    avg(total_violation_rows) AS mean_total_violation_rows,\n    avg(critical_violation_rows) AS mean_critical_violation_rows\n  FROM matched\n)\nSELECT * FROM stats;'})

