Action: run_sql({'query': 'WITH scored AS (\n  SELECT inspection_score\n  FROM inspections\n  WHERE inspection_score IS NOT NULL\n)\nSELECT\n  COUNT(*) AS scored_inspections,\n  COUNT(DISTINCT i.slchd_establishment_key) AS establishments_with_scored_inspections,\n  ROUND(AVG(inspection_score), 2) AS mean_score,\n  MEDIAN(inspection_score) AS median_score,\n  MIN(inspection_score) AS min_score,\n  MAX(inspection_score) AS max_score,\n  STDDEV_SAMP(inspection_score) AS sd_score,\n  QUANTILE_CONT(inspection_score, 0.25) AS p25_score,\n  QUANTILE_CONT(inspection_score, 0.75) AS p75_score\nFROM inspections i\nWHERE inspection_score IS NOT NULL;'})

Action: run_sql({'query': "SELECT\n  CASE\n    WHEN inspection_score = 0 THEN '0'\n    WHEN inspection_score BETWEEN 1 AND 4 THEN '1–4'\n    WHEN inspection_score BETWEEN 5 AND 9 THEN '5–9'\n    WHEN inspection_score BETWEEN 10 AND 19 THEN '10–19'\n    WHEN inspection_score BETWEEN 20 AND 29 THEN '20–29'\n    ELSE '30+'\n  END AS score_band,\n  CASE\n    WHEN inspection_score = 0 THEN 1\n    WHEN inspection_score BETWEEN 1 AND 4 THEN 2\n    WHEN inspection_score BETWEEN 5 AND 9 THEN 3\n    WHEN inspection_score BETWEEN 10 AND 19 THEN 4\n    WHEN inspection_score BETWEEN 20 AND 29 THEN 5\n    ELSE 6\n  END AS band_order,\n  COUNT(*) AS inspection_count,\n  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_scored_inspections\nFROM inspections\nWHERE inspection_score IS NOT NULL\nGROUP BY 1, 2\nORDER BY band_order;"})

Action: run_sql({'query': 'SELECT\n  it.description AS inspection_type,\n  COUNT(*) AS scored_inspections,\n  ROUND(AVG(i.inspection_score), 2) AS mean_score,\n  MEDIAN(i.inspection_score) AS median_score,\n  MIN(i.inspection_score) AS min_score,\n  MAX(i.inspection_score) AS max_score\nFROM inspections i\nLEFT JOIN inspection_types it ON i.inspection_type_id = it.inspection_type_id\nWHERE i.inspection_score IS NOT NULL\nGROUP BY 1\nORDER BY scored_inspections DESC;'})

Action: run_sql({'query': 'SELECT\n  EXTRACT(YEAR FROM inspection_date)::INTEGER AS inspection_year,\n  COUNT(*) AS scored_inspections,\n  ROUND(AVG(inspection_score), 2) AS mean_score,\n  MEDIAN(inspection_score) AS median_score\nFROM inspections\nWHERE inspection_score IS NOT NULL\nGROUP BY 1\nORDER BY inspection_year;'})

Action: run_sql({'query': 'SELECT\n  COUNT(*) AS google_establishments,\n  COUNT(slchd_establishment_key) AS matched_to_slchd,\n  COUNT(*) - COUNT(slchd_establishment_key) AS without_matched_inspection_history,\n  ROUND(100.0 * COUNT(slchd_establishment_key) / COUNT(*), 2) AS pct_matched,\n  ROUND(100.0 * (COUNT(*) - COUNT(slchd_establishment_key)) / COUNT(*), 2) AS pct_without_matched_history\nFROM establishments;'})

