Action: run_sql({'query': "WITH annual AS (\n  SELECT\n    i.slchd_establishment_key,\n    EXTRACT(YEAR FROM i.inspection_date)::INTEGER AS year,\n    SUM(CASE WHEN vc.critical THEN COALESCE(v.violation_occurrences, 1) ELSE 0 END) AS critical_violations\n  FROM inspections i\n  LEFT JOIN violations v ON v.inspection_id = i.inspection_id\n  LEFT JOIN violation_codes vc ON vc.violation_code_id = v.violation_code_id\n  WHERE i.inspection_date >= CURRENT_DATE - INTERVAL '5 years'\n  GROUP BY 1, 2\n), endpoints AS (\n  SELECT\n    slchd_establishment_key,\n    MIN(year) AS first_year,\n    MAX(year) AS last_year,\n    ARG_MIN(critical_violations, year) AS first_year_critical,\n    ARG_MAX(critical_violations, year) AS last_year_critical\n  FROM annual\n  GROUP BY 1\n  HAVING COUNT(*) >= 2\n), changes AS (\n  SELECT\n    e.slchd_establishment_key,\n    k.name,\n    k.address,\n    k.city,\n    e.first_year,\n    e.last_year,\n    e.first_year_critical,\n    e.last_year_critical,\n    e.last_year_critical - e.first_year_critical AS change\n  FROM endpoints e\n  JOIN establishment_keys k USING (slchd_establishment_key)\n  WHERE e.last_year_critical <> e.first_year_critical\n)\nSELECT * FROM changes\nORDER BY change DESC, name\nLIMIT 50"})

