Action: run_sql({'query': "WITH annual AS (\n  SELECT i.slchd_establishment_key, EXTRACT(YEAR FROM i.inspection_date)::INTEGER AS year,\n         SUM(CASE WHEN vc.critical THEN COALESCE(v.violation_occurrences,1) ELSE 0 END) AS critical_violations\n  FROM inspections i LEFT JOIN violations v ON v.inspection_id=i.inspection_id\n  LEFT JOIN violation_codes vc ON vc.violation_code_id=v.violation_code_id\n  WHERE i.inspection_date >= CURRENT_DATE - INTERVAL '5 years'\n  GROUP BY 1,2\n), endpoints AS (\n  SELECT slchd_establishment_key, MIN(year) first_year, MAX(year) last_year,\n         ARG_MIN(critical_violations,year) first_critical, ARG_MAX(critical_violations,year) last_critical\n  FROM annual GROUP BY 1 HAVING COUNT(*)>=2\n), ranked AS (\n  SELECT k.name, k.address, k.city, e.first_year, e.last_year, e.first_critical, e.last_critical,\n         e.last_critical-e.first_critical AS change,\n         CASE WHEN e.last_critical>e.first_critical THEN 'Up' ELSE 'Down' END AS direction\n  FROM endpoints e JOIN establishment_keys k USING(slchd_establishment_key)\n  WHERE e.last_critical<>e.first_critical\n), top_changes AS (\n  SELECT * FROM ranked QUALIFY ROW_NUMBER() OVER (PARTITION BY direction ORDER BY CASE WHEN direction='Up' THEN change ELSE -change END DESC, name)<=10\n)\nSELECT * FROM top_changes ORDER BY direction, change DESC, name"})

